'use strict';
const models={joint:'Общий бюджет',proportional:'Взносы по доходам',equal:'Равные взносы',traditional:'Семейные обязанности'},usd=n=>LifelineEconomy.toUSD(n),clock=()=>S.age+(S.t||0);
const surveys={USA:{note:'США, опрос Bankrate / YouGov, декабрь 2025, опубликован в 2026: 38% опрошенных пар полностью объединяют финансы, 36% сочетают общие и личные счета, 26% держат счета раздельно. Это данные о счетах, а не о формуле распределения расходов.',source:'https://www.bankrate.com/f/102997/x/62268aa83c/couples-finances-press-release-2026.pdf',joint:'38% опрошенных пар полностью объединяют финансы'},GBR:{note:'Великобритания, YouGov, 2024: среди совместно живущих пар, где оба работают, 46% делят счета поровну, 38% — по доходам. 24% перечисляют все доходы на общий счёт. Вопросы разные, эти доли не складываются.',source:'https://yougov.com/en-gb/articles/50381-what-is-the-fairest-way-for-couples-to-split-household-bills',joint:'24% перечисляют все доходы на общий счёт',equal:'46% делят счета поровну',proportional:'38% делят счета по доходам'},FRA:{note:'Франция, исследование Insee за 2010 год, опубликованное в 2012: 74% состоящих в браке пар из выборки полностью объединяли доходы. Выборка: живут вместе не менее года, хотя бы один работает или ищет работу. Данные исторические.',source:'https://www.insee.fr/fr/statistiques/1281044',joint:'74% состоящих в браке пар из выборки объединяли доходы (2010)'}};
function live(){return !!(S.fam.married&&S.fam.partner?.alive&&!S.fam.partner.divorced&&!ptAway()&&S.job!=='prison');}
function key(){return String(S.fam.partner?.name?.full||S.fam.partner?.name||'partner')+'|'+(S.fam.marriedAt??S.fam.marriages??0);}
function state(){if(!live())return null;const id=key();if(S.lifelineCouple?.key!==id)S.lifelineCouple={key:id,model:null,partnerReserve:0,agreedSelf:0,agreedPartner:0,lastPrompt:-1,needsInitial:false,scale:1,covered:0,coverYear:S.age};return S.lifelineCouple;}
function numbers(model=state()?.model){const c=state();if(!c)return null;const own=Math.max(0,S.income||0),partner=Math.max(0,S.fam.partner.inc||0),kids=homeOthers().kids.filter(k=>S.age-k.bornAt<18).length,cost=incomeAt(C(),.5)*.36*(1+kids*.2)*(c.scale||1),traditional=!!(S.fam.partner.lifelineTraditional||S.fam.partner.arr)&&['sa','mena'].includes(C().p),provider=S.sex==='M'?'self':S.sex==='F'?'partner':own>=partner?'self':'partner';let selfDue=model==='equal'?cost/2:model==='traditional'?provider==='self'?cost:0:cost*(own+partner>0?own/(own+partner):.5),partnerDue=cost-selfDue;const cover=c.coverYear===S.age?c.covered||0:0,partnerGap=Math.max(0,partnerDue-partner-c.partnerReserve-cover),selfGap=Math.max(0,selfDue-own-Math.max(0,S.money)),householdGap=Math.max(0,cost-own-partner-Math.max(0,S.money)-c.partnerReserve-cover);return {own,partner,cost,selfDue,partnerDue,traditional,provider,partnerGap,selfGap,householdGap,coverNeeded:Math.max(partnerGap,householdGap,Math.max(0,(c.allocationShortfall||0)-cover))};}
