function resolve(choice){if(LifelineMoments.pending()?.id!=='lifeline-couple-finance')return false;const c=state(),n=numbers();if(!c)throw Error('Совместный бюджет сейчас недоступен');const allowed=LifelineMoments.pending().view.choices.find(k=>k.k===choice&&!k.dis);if(!allowed)throw Error('Этот вариант сейчас недоступен');if(choice==='cover'){cover();return true;}if(choice!=='keep'){if(n.traditional&&choice!=='traditional')throw Error('Семья придерживается другой договорённости');if(!models[choice])throw Error('Неизвестная модель бюджета');if(choice==='joint'&&(c.partnerReserve>0||c.allocationShortfall>0)){const joined=c.partnerReserve-(c.allocationShortfall||0);S.money+=joined;book('Накопления и обязательства партнёра в общем бюджете',joined);c.partnerReserve=0;c.allocationShortfall=0;}c.model=choice;c.agreedSelf=n.own;c.agreedPartner=n.partner;log('Вы договорились: '+models[choice].toLowerCase()+'.','note');}c.lastPromptFingerprint=fingerprint(numbers());return true;}
function cover(){const c=state(),n=numbers();if(!c||n.coverNeeded<=0)throw Error('Недостающей суммы сейчас нет');if(S.money<n.coverNeeded)throw Error('Недостаточно доступных денег');S.money-=n.coverNeeded;book('Вы покрыли недостающую часть общих расходов',-n.coverNeeded);if(c.coverYear!==S.age){c.coverYear=S.age;c.covered=0;}c.covered+=n.coverNeeded;c.allocationShortfall=Math.max(0,(c.allocationShortfall||0)-n.coverNeeded);c.lastPromptFingerprint=fingerprint(numbers());log('Вы доплатили за партнёра '+usdStr(n.coverNeeded)+' из собственных денег.','warm');}
function perform(payload){if(S.pending||LifelineMoments.pending())throw Error('Сначала завершите текущий выбор');if(payload.mode==='cover')cover();else prompt('manual');}
function partnerSavings(base,factor){const c=state();if(!c?.model)return base;const net=base/factor;c.reserveEarned=(c.reserveEarned||0)+net;if(c.model==='joint'||c.model==='traditional'&&numbers().provider==='partner')return net;return 0;}
function install(){const original=finances;finances=function(...args){const c=state();if(c)c.reserveEarned=0;const result=original.apply(this,args);if(c?.model&&live()&&c.model!=='joint'&&!(c.model==='traditional'&&numbers().provider==='partner')){const beforeAllocation=S.money+c.partnerReserve+(c.reserveEarned||0)-(c.allocationShortfall||0);const n=numbers(),baseline=n.own>0?n.cost/2:0,partnerBaseline=n.partner>0?n.cost/2:0,nextReserve=c.partnerReserve+(c.reserveEarned||0)+partnerBaseline-n.partnerDue-(c.allocationShortfall||0);let delta=baseline-n.selfDue;if(delta>0&&nextReserve<0)delta=Math.max(0,delta+nextReserve);S.money+=delta;if(delta)book('Ваша доля общих расходов по договорённости',delta);c.partnerReserve=Math.max(0,nextReserve);c.allocationShortfall=Math.max(0,-nextReserve);c.lastAllocation={before:beforeAllocation,after:S.money+c.partnerReserve-c.allocationShortfall};}return result;};}
function observe(before,command){if(['snapshot','restore','new'].includes(command))return;if(S.phase!=='life'||S.age<18||!live())return;if(before&&(!before.fam.married||before.fam.partner?.name?.full!==S.fam.partner.name?.full)){if(before.flags?.cand?.arr)S.fam.partner.lifelineTraditional=true;state().needsInitial=true;}const c=state(),n=numbers();if(S.pending||LifelineMoments.pending())return;if(!c.model){if(c.needsInitial||command==='advance')prompt();return;}if(c.lastPromptFingerprint===fingerprint(n))return;const threshold=incomeAt(C(),.5)*.1,changed=(now,old)=>Math.abs(now-old)>threshold&&Math.abs(now-old)/Math.max(old,1)>=.3;if(n.partnerGap>0||n.selfGap>0||n.householdGap>0)prompt('shortfall');else if(changed(n.partner,c.agreedPartner))prompt('partner-change');else if(changed(n.own,c.agreedSelf))prompt('self-change');}
function summary(){const c=state(),n=numbers();if(!c)return null;return {model:c.model,title:models[c.model]||'Ещё не договорились',traditional:n.traditional,expectation:n.traditional?(n.provider==='self'?'Вы оплачиваете общий быт; партнёр заботится о семье':'Партнёр оплачивает общий быт; вы заботитесь о семье'):null,ownIncome:usd(n.own),partnerIncome:usd(n.partner),expenses:usd(n.cost),selfDue:usd(n.selfDue),partnerDue:usd(n.partnerDue),partnerReserve:usd(c.partnerReserve),shortfall:usd(n.coverNeeded),canCover:n.coverNeeded>0&&S.money>=n.coverNeeded,stats:surveys[S.cur]||null};}
